        "start": 3356,
        "raw": "集会所広場整備事業\n\nコロナ禍において屋外での健康づくり活動の需要 感染防止対策だけに限らず、新しい生活様式への\nが増加しているため、集会所の駐車場を改修し、 移行など、大きな変化が求められる状況で迅速な\n地域住民のための屋外広場として活用する。\n支援体制を講じることができた。\n\n1,518\n\n",
