        "start": 1330,
        "raw": "\nの育成伝承事業」があり、令和 5 年度は「学校経営校長戦略事\n\nこの２色は南部町色１色になったのだろうか？\n\n業」\n「教室黒板ホワイトボード化事業」\n「会見第二小学校創立 150\n\n「南部町はこんな町！」が語れるだろうか。\n\n周年記念事業」に繰り入れられました。\n\n２色のまま残っていくのもありかなと思います。\n〈ハード面〉\n\n○近年、課題を抱えた児童生徒が増加し、学習支援員の存在や役\n\n施設のコミュニティ化をしませんか。\n\n割が益々重要になっています、現状の人数や対応で十分なので\n\n・学校施設を市民開放できるスペースを作る。\n\nしょうか。\n\n例・・・図書館・フリースペース（交流広場）\n\n⇒（事務局回答）\n\n・・・プールを町民プールとして運営する。\n\n・児童生徒へ直接、学習の支援を行う職員として、7 名の学習支援",
        "note": "年度別教育行政点検評価の本文で明記された事業名のみ。政策見出しや委員の提案を新事業にしない。数値・政策評価を事業評価へ転記しない。",
