        "raw": "\n見交換することはとても有意義なことであり、是非とも実施し\n\n業者を決定する方式（プロポーザル）で、委託先を決定しました。\n\nてほしい。\n\n〇P11 地域とともに歩む学校づくり推進事業（教育委員会事務局）\n\n〇CS が「地域学校協働活動」を具体的にどうするかというような\n\n・中学校区単位の小中一貫教育？\n\n“打ち合わせ”目的のように活用されている傾向が見受けられ\n\n→方針では「保・小中一貫教育」\n\nつつあるので（県内で）、南部町ではどうなのか。CS はあくま ⇒（事務局回答）\nでも「学校運営のための組織体」であるので、そのあたりの行\n\n「地域とともに歩む学校づくり推進事業」における中学校区 CS\n\n政としての指導助言は欠かせないと思う。",
