        "raw": "\n重要であるとともに、英語教員の指導力向上も欠かせないと思\nわれる。\n\n「ミカエルプログラム」等、園から中まで一貫した取組を推進\nしています。\n〇P18ICT 活用事業\n・クラウド型ドリル教材？\n\n1\n\n\n⇒（事務局回答）\nインターネットにアクセスし、タブレット端末で利用するドリ\nル教材のことです。理解度にあわせた問題提示など、個々の児\n童生徒に合わせた学びが提供できます。\n〇（2）年長時からの「まち未来科」の実施状況はどうなっていま\nすか。\n⇒（事務局回答）\n各校、「まち未来科」の年間指導計画にそって実践しています。\n年長児は「まち未来科」の遊びを設定するのではなく、保育士が\n４つの力の視点で遊びを捉えることで遊びの充実につなげてい",
