        "raw": "\n〇域学校協働活動推進員の職務実態について（地域人材と学校と\nの調整のほかに携わっている業務はあるか）\n。\n⇒（事務局回答）\nCS 委員会で立案した活動や学校支援活動等を実際に行っていま\nす。\n〇コンピューター整備事業（中学校）で南中は教職員用パソコン\n「貸借」27 台、同じく法中は「購入」30 台とあったが、貸借と\n購入をどのように区別しているのか（なお、３小学校は「貸借」）\n。\n⇒（事務局回答）\n法中以外の４校は一括で「貸借」にて契約中ですが、契約時期が\nずれている法中のみ R４年度の更新となりました。この度活用\nした補助金は「購入」に限定されていましたので、\n「購入」とし\nました。\n２. 子ども達が安心し ○不登校児童生徒が依然増加傾向にあるとの事。\n\n○「デジタルさくらんぼ」とは。",
