        "raw": "\n移住定住総合相談窓口の拡充を行い移住希望者の支援を行うとともに、空き家情報の情報発信や住宅に\n関する各種補助制度を活用することで、移住者が日吉津村で安心して定住できる村をめざします。\n主な事業の概要\n【事業名】\n\n移住定住支援事業\n\n【担当課】\n\n総合政策課\n\n移住定住総合相談窓口を設置し、結婚から就労、定住まで、IJUターン希望者を総合的に\n【事業概要】\n支援します。\n\n事業内容\n（P）\n\n【担当課】\n\n総合政策課\n\n【事業名】\n\n移住定住支援金\n\n【事業概要】\n\n東京23区から日吉津村に移住し、鳥取県が指定する事業所に就職した方へ交付金を支給す\nることで移住しやすい環境を整えます。",
