        "raw": "■英語検定受検費補助事業\n①R4:300千円\n■新たに英検3級以上を受験した生徒が\n②R4:116千円\n4.0% 増えたため、昨年度より実績が1%上がっ\n③5年生以上の英語科の授業において、オンライン英会話事業を実施する予定で\nた\nある\n④本事業はエドテック補助金事業を活用しているため、R4年度は町費の持ち出し\nなしで実施するが、学習効果があればR5年度以降の実施を検討していく",
        "note": "関連事業欄の明示された予算・決算・実施内容の単位。併記事業は分割せず、政策指標を事業評価に転用しない。金額列は未抽出。前年度比較値や公表年を対象年度と混同しない。"
