        "raw": "\n生活保護受給者就労支援事 結びつく者の数は伸び悩んでいる。\n業に参加 ④ 生活福\n12 業に参加し、就労開始と 実績値 人 - 70 49 54 56 66 56 現在、生活保護を新たに受給する被保護者について\nし、就労 遅延 祉課\nなった当該年度の人数。 は、原則事業に参加していただくこととしており、引き\n開始と\n続き関係機関とも連携しながら、被保護者の自立に向け\nなった人\n達成率 ％ - - - 71.1% 68.3% 75.0% 58.9% た支援に取り組んでいく。\n数\n鳥取市国 目標値 ％ - - - 81.0 82.0 83.0 84.0 85.0 先発医薬品をジェネリック医薬品に切り替えた場合の\n民健康保 厚生労働省が発表する、鳥 差額通知を３回送付し、ジェネリック医薬品の利用促進\n険におけ 取市国民健康保険における と、ジェネリック医薬品への切り替えによる、被保険者\n(1201) 13 るジェネ\n① 保険年\n薬剤に占める当該年度の 実績値 ％ - 79.6 80.9 80.6 81.2 82.8 85.0 の医療費負担の軽減につなげた。\n安心でき 順調 金課\nリック医 ジェネリック医薬品の数量 引き続き、安心できる社会保障制度の運営のため、\nる社会保 薬品の普 ベースによる普及割合。 ジェネリック医薬品の利用を促進し、医療費の適正化を\n障制度の 及率 図る。\n達成率 ％ - - - 99.5% 99.0% 99.8% 101.2%\n運営\n利用者が必要な介護サービスを適切に提供するため、\n目標値 件 - - - 490 490 560 560 580 介護支援専門員が作成するケアプラン点検を実施してい\nる。点検において、ケアプランの基本的事項を検証確認\n介護給付 するとともに自立支援のためにケアマネジメントについ\n適正化事 て、介護支援専門員の「気づき」を促しながら取り組む\n③\n業におけ ケアプラン点検を行った当 実績値 ことが求められる。 長寿社\n14 件 - 528 190 348 805 607 417 やや\nるケアプ 該年度のプラン件数。 令和５年度までは達成率が100％を超えていたが、ケ 会課\n遅延\nラン点検 アプラン点検の数が多くても実際のプランに改善が見ら\n実施件数 れなければ意味がないことから、令和６年度はケアプラ\nン点検の目的である質の向上を図ることを意識し、面談\n達成率 ％ - - - 71.0% 164.3% 108.4% 74.5% に力を入れた。しかし、結果的に点検プラン数は伸びな\nかった。",
        "note": "政策KPI表内で名称と活動説明が明記された事業のみ。KPI行・政策自体は事業化せず、指標値や政策評点も引き継がない。複数年度表から対象年度を推測しない。",
